macro_rules! predecessor_count_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function predecessor_count in module {}", module_path!());
    };
}

mkfn!{
    predecessor_count_introspect!();
    fn predecessor_count (body : & Body < '_ >) -> IndexVec < BasicBlock , usize > { let mut predecessors : IndexVec < _ , _ > = body . basic_blocks . predecessors () . iter () . map (| ps | ps . len ()) . collect () ; predecessors [START_BLOCK] += 1 ; predecessors }
}
